"""Shadowsocks AEAD client: known-answer vectors and framing.

**Nothing in this file opens a network socket.** The loopback fixture in
`ShadowsocksLoopbackTests` binds 127.0.0.1 and nothing else; the crypto
tests below it are pure byte comparisons.

Where every vector came from
----------------------------

The hard part of this protocol is not the AEAD -- that is `cryptography`,
which is OpenSSL. The hard part is the three pieces of glue around it, and
each one is pinned here to a source that is not this repository:

* **`EVP_BytesToKey`** -- generated by running the OpenSSL CLI, which *is*
  the reference implementation of this function. The exact command is
  recorded beside the vectors. `openssl enc` prints the key and IV it
  derived; Shadowsocks takes the same derived byte stream and uses the
  first `key_size` bytes of it. The 16-byte and 32-byte vectors for the
  same password are cross-checked against each other to confirm they are
  one continuous stream rather than two independent derivations.

* **HKDF-SHA1** -- RFC 5869 Appendix A, Test Cases 5 and 6 (the SHA-1
  cases). Checked against both this module's output and an independent
  HMAC loop written in this file, so a bug would have to appear in two
  implementations and in the RFC simultaneously.

  *Test Case 4 is deliberately absent.* Its PRK was reproduced exactly,
  but the OKM value recalled for it did not match either implementation.
  Rather than record a vector that could not be corroborated, it was
  dropped -- see the note in `HkdfSha1KnownAnswerTests`.

* **AES-GCM** -- the GCM specification's own test cases 1, 2, 13 and 14
  (Appendix B of McGrew & Viega's submission, the vectors NIST SP 800-38D
  is built on). These test `cryptography`, not our code, and are kept
  because a cipher that silently changed behaviour would break every
  Shadowsocks proxy at once with no other signal.

* **ChaCha20-Poly1305** -- RFC 8439 section 2.8.2, the worked AEAD example
  with its "Ladies and Gentlemen" plaintext.

* **The composition** -- the subkey derivation, the nonce sequence, the
  chunk framing and the request header have **no published known-answer
  vector**. None exists: the Shadowsocks specification describes the
  construction in prose and ships no test vectors, and the reference
  implementations have none either. So instead of inventing one and
  calling it authoritative, the composition is tested against a **second,
  independent implementation written in this file** (`_ReferenceServer`),
  built from the specification using `hashlib`, `hmac` and raw
  `cryptography` primitives, and sharing no code with
  `proxies.shadowsocks`. Agreement between two implementations written
  from the same prose is weaker evidence than a published vector, and
  that is stated rather than papered over.
"""

import binascii
import hashlib
import hmac
import socket
import struct
import threading

from cryptography.hazmat.primitives.ciphers.aead import AESGCM, ChaCha20Poly1305
from django.test import TestCase, override_settings

from proxies.models import ProbeErrorKind, ProxyProtocol
from proxies.probing import (
    ProbeUnsupported,
    ProxyTarget,
    SocketProber,
    probe_batch,
)
from proxies.shadowsocks import (
    CIPHERS,
    MAX_PAYLOAD,
    NONCE_SIZE,
    DecryptionFailed,
    NonceCounter,
    ShadowsocksError,
    ShadowsocksSession,
    UnsupportedCipher,
    cipher_spec,
    derive_subkey,
    evp_bytes_to_key,
    is_ss2022,
    socks5_address,
)


def unhex(text):
    return binascii.unhexlify(text.replace(" ", "").replace("\n", ""))


def hexs(data):
    return binascii.hexlify(data).decode()


# ---------------------------------------------------------------------------
# 1. EVP_BytesToKey -- vectors from the OpenSSL CLI
# ---------------------------------------------------------------------------


class EvpBytesToKeyKnownAnswerTests(TestCase):
    """Master-key derivation against OpenSSL, the reference implementation.

    Each vector was produced by running, on OpenSSL 3.5.7::

        openssl enc -aes-256-cbc -md md5 -nosalt -pass pass:<PASSWORD> -P

    which prints `key=` (32 bytes) and `iv=` (16 bytes). `EVP_BytesToKey`
    produces one continuous byte stream and hands the front of it to the
    key and the next slice to the IV, so `key || iv` is the first 48 bytes
    of the derivation -- which is why the same command also yields the
    16-byte vector, and why `test_sizes_are_prefixes_of_one_stream` is a
    real check on the implementation rather than a tautology.
    """

    # password -> (key32, iv16) exactly as openssl printed them.
    OPENSSL = {
        "test-password": (
            "dfb450efddbb5387197c84460623675b69f2cebcd8ef520a3dfddef7c3d540b2",
            "2ea0e2b6959ef236989bf15f140ed95a",
        ),
        "": (
            "d41d8cd98f00b204e9800998ecf8427e59adb24ef3cdbe0297f05b395827453f",
            "8b8154f03b75f58a6c702235bf643629",
        ),
        "p": (
            "83878c91171338902e0fe0fb97a8c47adf601e5227e36e2167a33be52ff2920a",
            "d5832044cbea982af8a24aca68b3b33f",
        ),
        "correct horse battery staple": (
            "9cc2ae8a1ba7a93da39b46fc1019c481f5eed4f36a1de6859cad92c665562831",
            "a898665fe1740c48a4c4d00d3b6dc17a",
        ),
        "sS-p@ssw0rd!": (
            "cdb23e5717c720f6402d22783eb51b0eadb292b69011b78d6b3e2ab26f011cb1",
            "b1fdd909b999657d3ffdb82c60c92847",
        ),
        # Non-ASCII, to pin that the password is hashed as its UTF-8 bytes.
        #
        # This one is NOT from the `-pass pass:` form above. On Windows the
        # OpenSSL build converts a non-ASCII argv argument to the local ANSI
        # codepage before using it, so passing "ee-acute ee-acute" on the
        # command line silently derives from the cp1252 bytes e9 e9 rather
        # than from the UTF-8 bytes c3 a9 c3 a9 -- a vector that looks
        # authoritative and records the host's codepage instead of the
        # algorithm. Sourced through a file, which argv conversion does not
        # touch:
        #
        #     printf '\303\251\303\251' > pw.bin
        #     openssl enc -aes-256-cbc -md md5 -nosalt -pass file:pw.bin -P
        #
        # An ASCII control through the same file form reproduces the
        # `test-password` vector above byte for byte, which is what
        # establishes that the file path itself is faithful.
        "éé": (
            "0c63a3452c46569a70c4fedbf2a84e8688c8c7c0164bb87c841b9c46ac8fd2f3",
            "2dbe45c98fe19318657d0a6a032e6ef5",
        ),
    }

    def test_32_byte_keys_match_openssl(self):
        for password, (key32, _iv) in self.OPENSSL.items():
            with self.subTest(password=password):
                self.assertEqual(
                    hexs(evp_bytes_to_key(password.encode("utf-8"), 32)), key32
                )

    def test_16_byte_keys_match_openssl(self):
        """aes-128-gcm's key is the front of the same stream."""
        for password, (key32, _iv) in self.OPENSSL.items():
            with self.subTest(password=password):
                self.assertEqual(
                    hexs(evp_bytes_to_key(password.encode("utf-8"), 16)), key32[:32]
                )

    def test_sizes_are_prefixes_of_one_stream(self):
        """key32 || iv16 is the first 48 bytes, not two derivations.

        This is the property that catches an implementation which
        re-seeds the MD5 chain per output block -- a plausible-looking bug
        that produces a correct 16-byte key and a wrong 32-byte one.
        """
        for password, (key32, iv16) in self.OPENSSL.items():
            with self.subTest(password=password):
                self.assertEqual(
                    hexs(evp_bytes_to_key(password.encode("utf-8"), 48)),
                    key32 + iv16,
                )

    def test_the_empty_password_derives_from_md5_of_nothing(self):
        """An independent cross-check on the first block of the chain."""
        self.assertEqual(
            evp_bytes_to_key(b"", 16), hashlib.md5(b"").digest()
        )

    def test_the_chain_feeds_the_previous_digest_back_in(self):
        """D_2 = MD5(D_1 || password), spelled out against hashlib."""
        password = b"test-password"
        first = hashlib.md5(password).digest()
        second = hashlib.md5(first + password).digest()
        self.assertEqual(evp_bytes_to_key(password, 32), first + second)

    def test_a_non_positive_length_is_refused(self):
        with self.assertRaises(ValueError):
            evp_bytes_to_key(b"x", 0)

    def test_a_str_password_is_refused_rather_than_guessed_at(self):
        """Encoding is the caller's decision; latin-1 vs utf-8 is a
        different key and a silently broken proxy."""
        with self.assertRaises(TypeError):
            evp_bytes_to_key("not bytes", 32)


# ---------------------------------------------------------------------------
# 2. HKDF-SHA1 -- RFC 5869 Appendix A
# ---------------------------------------------------------------------------


def reference_hkdf_sha1(ikm, salt, info, length):
    """RFC 5869 extract-and-expand, written out from the RFC.

    Independent of `proxies.shadowsocks`, which uses `cryptography`'s
    HKDF. Two implementations from one specification.
    """
    prk = hmac.new(salt, ikm, hashlib.sha1).digest()
    okm, block, counter = b"", b"", 1
    while len(okm) < length:
        block = hmac.new(prk, block + info + bytes([counter]), hashlib.sha1).digest()
        okm += block
        counter += 1
    return okm[:length]


class HkdfSha1KnownAnswerTests(TestCase):
    """RFC 5869 Appendix A, the SHA-1 cases.

    Only Test Cases 5 and 6 appear. Test Case 4's OKM could not be
    corroborated: the value recalled for it disagreed with both this
    file's independent HMAC loop and `cryptography`'s HKDF, which agree
    with each other. The honest conclusion is that the recalled value was
    wrong, not that two implementations share a bug -- but an
    uncorroborated vector is worth nothing as a test, so it is not here.
    TC5 and TC6 were recalled and matched both implementations exactly,
    and TC5 in particular exercises multi-block expansion (82 bytes = 5
    SHA-1 blocks), which is where an expand-step bug lives.
    """

    # RFC 5869 Appendix A, Test Case 5: SHA-1 with longer inputs/outputs.
    TC5_IKM = bytes(range(0x00, 0x50))
    TC5_SALT = bytes(range(0x60, 0xB0))
    TC5_INFO = bytes(range(0xB0, 0x100))
    TC5_OKM = (
        "0bd770a74d1160f7c9f12cd5912a06ebff6adcae899d92191fe4305673ba2ffe"
        "8fa3f1a4e5ad79f3f334b3b202b2173c486ea37ce3d397ed034c7f9dfeb15c5e"
        "927336d0441f4c4300e2cff0d0900b52d3b4"
    )

    # Test Case 6: zero-length salt and info.
    TC6_IKM = b"\x0b" * 22
    TC6_OKM = (
        "0ac1af7002b3d761d1e55298da9d0506b9ae52057220a306e07b6b87e8df21d0"
        "ea00033de03984d34918"
    )

    def test_case_5_matches_the_rfc(self):
        self.assertEqual(
            hexs(reference_hkdf_sha1(self.TC5_IKM, self.TC5_SALT, self.TC5_INFO, 82)),
            self.TC5_OKM,
        )

    def test_case_6_matches_the_rfc(self):
        """Zero-length salt is HMAC-keyed with HashLen zero bytes."""
        self.assertEqual(
            hexs(reference_hkdf_sha1(self.TC6_IKM, b"\x00" * 20, b"", 42)),
            self.TC6_OKM,
        )

    def test_derive_subkey_agrees_with_the_reference_loop(self):
        """Our subkey derivation against the RFC written out longhand.

        `derive_subkey` is HKDF-SHA1 with `info="ss-subkey"` and the salt
        taken from the wire, so this is the composition rather than the
        primitive.
        """
        master = evp_bytes_to_key(b"hunter2", 32)
        salt = bytes(range(32))
        self.assertEqual(
            derive_subkey(master, salt, 32),
            reference_hkdf_sha1(master, salt, b"ss-subkey", 32),
        )

    def test_a_different_salt_gives_a_different_subkey(self):
        master = evp_bytes_to_key(b"hunter2", 32)
        self.assertNotEqual(
            derive_subkey(master, b"\x00" * 32, 32),
            derive_subkey(master, b"\x01" * 32, 32),
        )

    def test_the_info_string_is_part_of_the_protocol(self):
        """`ss-subkey` is on the wire. Changing it changes every key."""
        master = evp_bytes_to_key(b"hunter2", 32)
        salt = b"\x07" * 32
        self.assertNotEqual(
            derive_subkey(master, salt, 32),
            reference_hkdf_sha1(master, salt, b"ss-subkey-v2", 32),
        )


# ---------------------------------------------------------------------------
# 3. The AEAD primitives themselves
# ---------------------------------------------------------------------------


class AeadPrimitiveKnownAnswerTests(TestCase):
    """The ciphers, against their own specifications' vectors.

    These test `cryptography` rather than anything written here. They are
    kept because the failure they catch -- a dependency upgrade changing
    AEAD behaviour -- would otherwise appear as "every Shadowsocks proxy
    went dead overnight" with no closer explanation.
    """

    def test_gcm_spec_case_1_aes_128_empty_plaintext(self):
        """GCM spec test case 1: zero key, zero IV, no plaintext."""
        self.assertEqual(
            hexs(AESGCM(b"\x00" * 16).encrypt(b"\x00" * 12, b"", None)),
            "58e2fccefa7e3061367f1d57a4e7455a",
        )

    def test_gcm_spec_case_2_aes_128_one_zero_block(self):
        self.assertEqual(
            hexs(AESGCM(b"\x00" * 16).encrypt(b"\x00" * 12, b"\x00" * 16, None)),
            "0388dace60b6a392f328c2b971b2fe78ab6e47d42cec13bdf53a67b21257bddf",
        )

    def test_gcm_spec_case_13_aes_256_empty_plaintext(self):
        self.assertEqual(
            hexs(AESGCM(b"\x00" * 32).encrypt(b"\x00" * 12, b"", None)),
            "530f8afbc74536b9a963b4f1c4cb738b",
        )

    def test_gcm_spec_case_14_aes_256_one_zero_block(self):
        self.assertEqual(
            hexs(AESGCM(b"\x00" * 32).encrypt(b"\x00" * 12, b"\x00" * 16, None)),
            "cea7403d4d606b6e074ec5d3baf39d18d0d1c8a799996bf0265b98b5d48ab919",
        )

    def test_rfc_8439_section_2_8_2_chacha20_poly1305(self):
        """RFC 8439's worked AEAD example, ciphertext and tag."""
        key = bytes(range(0x80, 0xA0))
        nonce = unhex("070000004041424344454647")
        aad = unhex("50515253c0c1c2c3c4c5c6c7")
        plaintext = (
            b"Ladies and Gentlemen of the class of '99: If I could offer you "
            b"only one tip for the future, sunscreen would be it."
        )
        expected = (
            "d31a8d34648e60db7b86afbc53ef7ec2a4aded51296e08fea9e2b5a736ee62d6"
            "3dbea45e8ca9671282fafb69da92728b1a71de0a9e060b2905d6a5b67ecd3b36"
            "92ddbd7f2d778b8c9803aee328091b58fab324e4fad675945585808b4831d7bc"
            "3ff4def08e4b7a9de576d26586cec64b6116"
            "1ae10b594f09e26a7e902ecbd0600691"  # the Poly1305 tag
        )
        self.assertEqual(
            hexs(ChaCha20Poly1305(key).encrypt(nonce, plaintext, aad)), expected
        )


# ---------------------------------------------------------------------------
# 4. Nonce handling
# ---------------------------------------------------------------------------


class NonceCounterTests(TestCase):
    """Little-endian, per-operation, with a defined rollover.

    The endianness bug this guards against is the single most common
    Shadowsocks client defect: the first chunk works either way because
    the counter is zero, and the second one fails. That presents as a
    flaky server rather than a broken client.
    """

    def test_starts_at_zero(self):
        self.assertEqual(NonceCounter().current(), b"\x00" * NONCE_SIZE)

    def test_increments_the_lowest_byte_first(self):
        """Little-endian: byte 0 moves, not byte 11."""
        counter = NonceCounter()
        counter.advance()
        self.assertEqual(counter.current(), b"\x01" + b"\x00" * 11)

    def test_a_big_endian_implementation_would_fail_this(self):
        counter = NonceCounter()
        for _ in range(255):
            counter.advance()
        self.assertEqual(counter.current(), b"\xff" + b"\x00" * 11)

    def test_carries_into_the_next_byte(self):
        """The 0xff -> 0x00,0x01 boundary."""
        counter = NonceCounter(seed=b"\xff" + b"\x00" * 11)
        counter.advance()
        self.assertEqual(counter.current(), b"\x00\x01" + b"\x00" * 10)

    def test_carries_across_several_bytes(self):
        counter = NonceCounter(seed=b"\xff\xff\xff" + b"\x00" * 9)
        counter.advance()
        self.assertEqual(counter.current(), b"\x00\x00\x00\x01" + b"\x00" * 8)

    def test_carries_into_the_top_byte(self):
        counter = NonceCounter(seed=b"\xff" * 11 + b"\x00")
        counter.advance()
        self.assertEqual(counter.current(), b"\x00" * 11 + b"\x01")

    def test_full_rollover_wraps_to_zero_rather_than_overflowing(self):
        """2**96 - 1 -> 0. Unreachable in practice, defined anyway: the
        alternative is an IndexError in a thread nobody is watching."""
        counter = NonceCounter(seed=b"\xff" * NONCE_SIZE)
        counter.advance()
        self.assertEqual(counter.current(), b"\x00" * NONCE_SIZE)

    def test_next_returns_the_current_value_and_then_advances(self):
        """Off-by-one here reuses nonce 0 or skips it; both are fatal."""
        counter = NonceCounter()
        self.assertEqual(counter.next(), b"\x00" * NONCE_SIZE)
        self.assertEqual(counter.next(), b"\x01" + b"\x00" * 11)
        self.assertEqual(counter.next(), b"\x02" + b"\x00" * 11)

    def test_the_sequence_matches_a_little_endian_integer(self):
        """Cross-checked against struct, not against itself."""
        counter = NonceCounter()
        for value in range(600):
            self.assertEqual(
                counter.next(), value.to_bytes(NONCE_SIZE, "little")
            )

    def test_a_wrong_sized_seed_is_refused(self):
        with self.assertRaises(ValueError):
            NonceCounter(seed=b"\x00" * 8)


# ---------------------------------------------------------------------------
# 5. Cipher registry
# ---------------------------------------------------------------------------


class CipherSpecTests(TestCase):
    def test_the_three_committed_ciphers_resolve(self):
        for name in ("aes-128-gcm", "aes-256-gcm", "chacha20-ietf-poly1305"):
            with self.subTest(name=name):
                self.assertEqual(cipher_spec(name).name, name)

    def test_key_sizes(self):
        self.assertEqual(cipher_spec("aes-128-gcm").key_size, 16)
        self.assertEqual(cipher_spec("aes-256-gcm").key_size, 32)
        self.assertEqual(cipher_spec("chacha20-ietf-poly1305").key_size, 32)

    def test_salt_size_equals_key_size(self):
        """The protocol's rule. Derived, so the two cannot disagree."""
        for spec in CIPHERS.values():
            with self.subTest(cipher=spec.name):
                self.assertEqual(spec.salt_size, spec.key_size)

    def test_every_tag_is_16_bytes(self):
        for spec in CIPHERS.values():
            self.assertEqual(spec.tag_size, 16)

    def test_names_are_case_and_whitespace_insensitive(self):
        self.assertEqual(cipher_spec("  AES-256-GCM ").name, "aes-256-gcm")

    def test_the_provider_spelling_of_chacha_is_accepted(self):
        """`chacha20-poly1305` in a CSV is a spelling, not a cipher we
        do not have. Rejecting it would park a probeable proxy in the
        skip bucket forever."""
        self.assertEqual(
            cipher_spec("chacha20-poly1305").name, "chacha20-ietf-poly1305"
        )

    def test_ss2022_is_unsupported_and_says_which_gap_it_is(self):
        for name in (
            "2022-blake3-aes-128-gcm",
            "2022-blake3-aes-256-gcm",
            "2022-blake3-chacha20-poly1305",
        ):
            with self.subTest(name=name):
                self.assertTrue(is_ss2022(name))
                with self.assertRaises(UnsupportedCipher) as caught:
                    cipher_spec(name)
                self.assertIn("2022", str(caught.exception))

    def test_an_empty_cipher_is_unsupported_rather_than_guessed(self):
        """Defaulting to aes-256-gcm would produce a confident 'dead'
        verdict on a proxy nobody finished configuring."""
        with self.assertRaises(UnsupportedCipher) as caught:
            cipher_spec("")
        self.assertIn("no cipher recorded", str(caught.exception))

    def test_a_pre_aead_stream_cipher_is_unsupported(self):
        """`aes-256-cfb` and friends are the removed stream ciphers. Not
        implemented, and not silently treated as the AEAD variant."""
        with self.assertRaises(UnsupportedCipher):
            cipher_spec("aes-256-cfb")


# ---------------------------------------------------------------------------
# 6. The address block
# ---------------------------------------------------------------------------


class Socks5AddressTests(TestCase):
    def test_ipv4_literal_uses_atyp_1(self):
        self.assertEqual(
            socks5_address("198.51.100.7", 8388),
            b"\x01" + bytes([198, 51, 100, 7]) + b"\x20\xc4",
        )

    def test_ipv6_literal_uses_atyp_4(self):
        block = socks5_address("2001:db8::1", 443)
        self.assertEqual(block[0], 0x04)
        self.assertEqual(len(block), 1 + 16 + 2)
        self.assertEqual(block[-2:], b"\x01\xbb")

    def test_a_hostname_uses_atyp_3_with_a_length_prefix(self):
        block = socks5_address("www.google.com", 443)
        self.assertEqual(block[0], 0x03)
        self.assertEqual(block[1], len(b"www.google.com"))
        self.assertEqual(block[2:-2], b"www.google.com")
        self.assertEqual(block[-2:], b"\x01\xbb")

    def test_the_port_is_big_endian(self):
        """Ports are network byte order even though nonces are not."""
        self.assertEqual(socks5_address("1.2.3.4", 443)[-2:], struct.pack("!H", 443))
        self.assertEqual(socks5_address("1.2.3.4", 1)[-2:], b"\x00\x01")
        self.assertEqual(socks5_address("1.2.3.4", 65535)[-2:], b"\xff\xff")

    def test_an_out_of_range_port_is_refused(self):
        for port in (0, 65536, -1):
            with self.subTest(port=port):
                with self.assertRaises(ValueError):
                    socks5_address("1.2.3.4", port)

    def test_an_over_long_hostname_is_refused(self):
        """255 is the length byte's ceiling; a longer name would be
        truncated into a different destination."""
        with self.assertRaises(ValueError):
            socks5_address("a" * 60 + "." + "b" * 200, 443)


# ---------------------------------------------------------------------------
# 7. Chunk framing
# ---------------------------------------------------------------------------


class ChunkFramingTests(TestCase):
    """`[len][tag][payload][tag]`, and the nonce sequence through it."""

    def session(self, cipher="aes-256-gcm", salt=None):
        return ShadowsocksSession(
            "hunter2", cipher, salt=salt or bytes(range(cipher_spec(cipher).key_size))
        )

    def test_the_salt_is_sent_once_in_front_of_the_first_chunk(self):
        session = self.session()
        first = session.seal(b"abc")
        self.assertEqual(first[:32], session.write_salt)
        second = session.seal(b"def")
        self.assertNotEqual(second[:32], session.write_salt)

    def test_chunk_layout_is_length_tag_payload_tag(self):
        session = self.session()
        sealed = session.seal(b"hello")[32:]  # drop the salt
        self.assertEqual(len(sealed), 2 + 16 + 5 + 16)

    def test_the_length_field_is_two_bytes_big_endian(self):
        """Decrypted independently with raw AESGCM, not with our reader."""
        salt = bytes(range(32))
        session = self.session(salt=salt)
        sealed = session.seal(b"x" * 300)[32:]
        subkey = reference_hkdf_sha1(
            evp_bytes_to_key(b"hunter2", 32), salt, b"ss-subkey", 32
        )
        plain_length = AESGCM(subkey).decrypt(b"\x00" * 12, sealed[: 2 + 16], None)
        self.assertEqual(plain_length, struct.pack("!H", 300))

    def test_the_payload_uses_the_next_nonce_not_the_same_one(self):
        """Reusing a nonce under one key is the one thing AEAD does not
        survive, and it is the natural shape of a naive implementation."""
        salt = bytes(range(32))
        session = self.session(salt=salt)
        sealed = session.seal(b"payload")[32:]
        subkey = reference_hkdf_sha1(
            evp_bytes_to_key(b"hunter2", 32), salt, b"ss-subkey", 32
        )
        body = sealed[2 + 16 :]
        self.assertEqual(
            AESGCM(subkey).decrypt(b"\x01" + b"\x00" * 11, body, None), b"payload"
        )

    def test_consecutive_chunks_keep_advancing_the_counter(self):
        """Chunk 2's length uses nonce 2, not nonce 0 again."""
        salt = bytes(range(32))
        session = self.session(salt=salt)
        session.seal(b"first")
        sealed = session.seal(b"second")
        subkey = reference_hkdf_sha1(
            evp_bytes_to_key(b"hunter2", 32), salt, b"ss-subkey", 32
        )
        self.assertEqual(
            AESGCM(subkey).decrypt(b"\x02" + b"\x00" * 11, sealed[: 2 + 16], None),
            struct.pack("!H", 6),
        )

    def test_a_payload_over_the_cap_is_split_rather_than_refused(self):
        """0x3FFF is a wire limit; making callers know it is how a 20 KB
        request becomes a bug report."""
        session = self.session()
        sealed = session.seal(b"z" * (MAX_PAYLOAD + 10))[32:]
        self.assertEqual(
            len(sealed),
            (2 + 16 + MAX_PAYLOAD + 16) + (2 + 16 + 10 + 16),
        )

    def test_exactly_the_cap_is_one_chunk(self):
        session = self.session()
        sealed = session.seal(b"z" * MAX_PAYLOAD)[32:]
        self.assertEqual(len(sealed), 2 + 16 + MAX_PAYLOAD + 16)

    def test_sealing_nothing_is_a_bug_and_is_refused(self):
        with self.assertRaises(ValueError):
            self.session().seal(b"")

    def test_all_three_ciphers_frame_identically_apart_from_key_size(self):
        for cipher, salt_size in (
            ("aes-128-gcm", 16),
            ("aes-256-gcm", 32),
            ("chacha20-ietf-poly1305", 32),
        ):
            with self.subTest(cipher=cipher):
                session = self.session(cipher)
                sealed = session.seal(b"hello")
                self.assertEqual(session.salt_size, salt_size)
                self.assertEqual(len(sealed), salt_size + 2 + 16 + 5 + 16)


class SessionReadTests(TestCase):
    """The read half: the server's salt, its own counter, its own key."""

    def roundtrip_session(self, cipher="aes-256-gcm"):
        return ShadowsocksSession("hunter2", cipher)

    def seal_as_server(self, password, cipher, salt, payloads):
        """Encrypt a reply the way a server would, with raw primitives."""
        spec = cipher_spec(cipher)
        subkey = reference_hkdf_sha1(
            evp_bytes_to_key(password.encode(), spec.key_size),
            salt,
            b"ss-subkey",
            spec.key_size,
        )
        aead = spec.aead(subkey)
        out, counter = bytearray(), 0
        for payload in payloads:
            out.extend(
                aead.encrypt(
                    counter.to_bytes(12, "little"), struct.pack("!H", len(payload)), None
                )
            )
            counter += 1
            out.extend(aead.encrypt(counter.to_bytes(12, "little"), payload, None))
            counter += 1
        return bytes(out)

    def test_a_server_reply_decrypts(self):
        for cipher in ("aes-128-gcm", "aes-256-gcm", "chacha20-ietf-poly1305"):
            with self.subTest(cipher=cipher):
                session = self.roundtrip_session(cipher)
                salt = bytes(range(session.salt_size))
                wire = self.seal_as_server("hunter2", cipher, salt, [b"pong"])
                session.begin_read(salt)
                length = session.open_length(wire[: session.length_block_size])
                self.assertEqual(length, 4)
                self.assertEqual(
                    session.open_payload(wire[session.length_block_size :], 4), b"pong"
                )

    def test_two_reply_chunks_advance_the_read_counter(self):
        session = self.roundtrip_session()
        salt = bytes(range(32))
        wire = self.seal_as_server("hunter2", "aes-256-gcm", salt, [b"one", b"two!"])
        session.begin_read(salt)
        offset = 0
        for expected in (b"one", b"two!"):
            length = session.open_length(
                wire[offset : offset + session.length_block_size]
            )
            offset += session.length_block_size
            self.assertEqual(
                session.open_payload(wire[offset : offset + length + 16], length),
                expected,
            )
            offset += length + 16

    def test_the_read_counter_is_independent_of_the_write_counter(self):
        """The client has already sent two chunks; the reply still starts
        at nonce zero. Sharing a counter between directions would make
        this test fail and a real connection hang."""
        session = self.roundtrip_session()
        session.seal(b"request one")
        session.seal(b"request two")
        salt = bytes(range(32))
        wire = self.seal_as_server("hunter2", "aes-256-gcm", salt, [b"pong"])
        session.begin_read(salt)
        length = session.open_length(wire[: session.length_block_size])
        self.assertEqual(
            session.open_payload(wire[session.length_block_size :], length), b"pong"
        )

    def test_a_wrong_password_fails_to_authenticate(self):
        """The one case the protocol does let us detect: bytes came back
        and they do not verify."""
        session = ShadowsocksSession("the-wrong-one", "aes-256-gcm")
        salt = bytes(range(32))
        wire = self.seal_as_server("hunter2", "aes-256-gcm", salt, [b"pong"])
        session.begin_read(salt)
        with self.assertRaises(DecryptionFailed):
            session.open_length(wire[: session.length_block_size])

    def test_a_wrong_cipher_fails_to_authenticate(self):
        session = ShadowsocksSession("hunter2", "chacha20-ietf-poly1305")
        salt = bytes(range(32))
        wire = self.seal_as_server("hunter2", "aes-256-gcm", salt, [b"pong"])
        session.begin_read(salt)
        with self.assertRaises(DecryptionFailed):
            session.open_length(wire[: session.length_block_size])

    def test_a_short_server_salt_is_a_protocol_error(self):
        session = self.roundtrip_session()
        with self.assertRaises(ShadowsocksError):
            session.begin_read(b"\x00" * 8)

    def test_reading_before_the_salt_arrives_is_refused(self):
        session = self.roundtrip_session()
        with self.assertRaises(ShadowsocksError):
            session.open_length(b"\x00" * session.length_block_size)

    def test_a_zero_length_chunk_is_rejected(self):
        """Losing framing sync has to stop here; reading on would
        misreport everything after it."""
        session = self.roundtrip_session()
        salt = bytes(range(32))
        subkey = reference_hkdf_sha1(
            evp_bytes_to_key(b"hunter2", 32), salt, b"ss-subkey", 32
        )
        block = AESGCM(subkey).encrypt(b"\x00" * 12, struct.pack("!H", 0), None)
        session.begin_read(salt)
        with self.assertRaises(ShadowsocksError):
            session.open_length(block)

    def test_a_length_over_the_cap_is_rejected(self):
        session = self.roundtrip_session()
        salt = bytes(range(32))
        subkey = reference_hkdf_sha1(
            evp_bytes_to_key(b"hunter2", 32), salt, b"ss-subkey", 32
        )
        block = AESGCM(subkey).encrypt(b"\x00" * 12, b"\xff\xff", None)
        session.begin_read(salt)
        with self.assertRaises(ShadowsocksError):
            session.open_length(block)

    def test_a_truncated_block_is_refused_rather_than_padded(self):
        session = self.roundtrip_session()
        session.begin_read(bytes(range(32)))
        with self.assertRaises(ShadowsocksError):
            session.open_length(b"\x00" * 4)

    def test_a_salt_of_the_wrong_size_for_the_cipher_is_refused(self):
        with self.assertRaises(ValueError):
            ShadowsocksSession("hunter2", "aes-128-gcm", salt=b"\x00" * 32)

    def test_each_session_generates_its_own_salt(self):
        """Salt reuse across connections reuses a (key, nonce) pair."""
        salts = {ShadowsocksSession("hunter2", "aes-256-gcm").write_salt for _ in range(20)}
        self.assertEqual(len(salts), 20)


# ---------------------------------------------------------------------------
# 8. An independent server, and the prober driving a real socket
# ---------------------------------------------------------------------------


class _ReferenceServer(threading.Thread):
    """A Shadowsocks server written from the specification, on loopback.

    Shares no code with `proxies.shadowsocks`: key derivation is
    `hashlib`, HKDF is the `hmac` loop above, and the AEAD comes straight
    from `cryptography`. That is what makes the end-to-end test a
    cross-check rather than a mirror.

    It does not connect anywhere. The destination address is parsed,
    recorded and discarded, and a canned reply is sealed and sent -- which
    is exactly what the probe needs to observe, and keeps the fixture free
    of any outbound network.

    `behaviour` selects what to simulate:
      "reply"        normal: decrypt the request, seal a reply
      "silence"      decrypt the request, say nothing, close -- the
                     ambiguous case the protocol is designed to produce
      "hold"         decrypt the request and then never answer, so the
                     probe hits its deadline rather than an EOF
      "garbage"      answer with bytes that cannot authenticate, without
                     reading the request at all (a port answered by
                     something that is not Shadowsocks)
      "wrong_key"    decrypt the request, seal the reply under a
                     *different* password
      "reply_blind"  do not try to decrypt the request; always reply,
                     sealed under this server's own password. The only
                     way to exercise "the client's password is wrong AND
                     the server replied anyway" -- a real server would
                     not, which is the whole difficulty of this protocol.

    Every behaviour drains the client's bytes before closing. Closing
    first makes the client's `send` race the reset and turns the test
    into a coin flip on which error kind comes back.
    """

    def __init__(self, password, cipher, behaviour="reply", reply=b"\x16\x03\x03pong"):
        super().__init__(daemon=True)
        self.password = password
        self.cipher = cipher
        self.behaviour = behaviour
        self.reply = reply
        self.spec = cipher_spec(cipher)
        self.received_address = None
        self.received_payload = b""
        self.error = None
        self._held = threading.Event()
        self._socket = socket.socket()
        self._socket.bind(("127.0.0.1", 0))
        self._socket.listen(1)
        self.address = self._socket.getsockname()

    def stop(self):
        self._held.set()
        try:
            self._socket.close()
        except OSError:
            pass

    # -- the protocol, written out from the spec -------------------------

    def _subkey(self, salt, password=None):
        master = self._evp(
            (password or self.password).encode("utf-8"), self.spec.key_size
        )
        return reference_hkdf_sha1(master, salt, b"ss-subkey", self.spec.key_size)

    @staticmethod
    def _evp(password, length):
        out, previous = b"", b""
        while len(out) < length:
            previous = hashlib.md5(previous + password).digest()
            out += previous
        return out[:length]

    def run(self):
        try:
            connection, _peer = self._socket.accept()
        except OSError:
            return
        try:
            self._serve(connection)
        except Exception as exc:  # noqa: BLE001 - recorded, asserted on
            self.error = exc
        finally:
            try:
                connection.close()
            except OSError:
                pass

    def _recv(self, connection, count):
        buffer = b""
        while len(buffer) < count:
            chunk = connection.recv(count - len(buffer))
            if not chunk:
                raise AssertionError("client closed mid-request")
            buffer += chunk
        return buffer

    def _drain(self, connection):
        """Read whatever the client sent, so our close is not a reset."""
        connection.settimeout(1.0)
        try:
            while connection.recv(65536):
                pass
        except (OSError, socket.timeout):
            pass

    def _serve(self, connection):
        connection.settimeout(5)

        if self.behaviour == "garbage":
            # Deliberately not a valid stream: the salt is fine (it is
            # just bytes) and nothing after it authenticates.
            connection.sendall(b"\x00" * (self.spec.salt_size + 2 + 16))
            self._drain(connection)
            return

        if self.behaviour == "reply_blind":
            # Read *something* so the client's send completes, without
            # attempting to decrypt it.
            connection.recv(65536)
            connection.sendall(self._sealed_reply())
            self._drain(connection)
            return

        salt = self._recv(connection, self.spec.salt_size)
        aead = self.spec.aead(self._subkey(salt))
        counter = 0

        def read_chunk():
            nonlocal counter
            head = self._recv(connection, 2 + 16)
            (length,) = struct.unpack(
                "!H", aead.decrypt(counter.to_bytes(12, "little"), head, None)
            )
            counter += 1
            body = self._recv(connection, length + 16)
            payload = aead.decrypt(counter.to_bytes(12, "little"), body, None)
            counter += 1
            return payload

        first = read_chunk()
        self.received_address, rest = self._parse_address(first)
        self.received_payload = rest
        if not rest:
            self.received_payload = read_chunk()

        if self.behaviour == "silence":
            return
        if self.behaviour == "hold":
            self._held.wait(timeout=10)
            return

        connection.sendall(self._sealed_reply())
        self._drain(connection)

    def _sealed_reply(self):
        password = (
            "a-completely-different-password"
            if self.behaviour == "wrong_key"
            else None
        )
        reply_salt = bytes(
            (index * 7 + 3) & 0xFF for index in range(self.spec.salt_size)
        )
        reply_aead = self.spec.aead(self._subkey(reply_salt, password))
        out = bytearray(reply_salt)
        out.extend(
            reply_aead.encrypt(
                (0).to_bytes(12, "little"), struct.pack("!H", len(self.reply)), None
            )
        )
        out.extend(reply_aead.encrypt((1).to_bytes(12, "little"), self.reply, None))
        return bytes(out)

    @staticmethod
    def _parse_address(block):
        atyp = block[0]
        if atyp == 0x01:
            host, offset = ".".join(str(byte) for byte in block[1:5]), 5
        elif atyp == 0x03:
            length = block[1]
            host, offset = block[2 : 2 + length].decode(), 2 + length
        elif atyp == 0x04:
            host, offset = block[1:17].hex(), 17
        else:
            raise AssertionError(f"bad ATYP {atyp}")
        (port,) = struct.unpack("!H", block[offset : offset + 2])
        return (host, port), bytes(block[offset + 2 :])


class ShadowsocksLoopbackTests(TestCase):
    """The real `SocketProber` against a loopback server.

    This binds 127.0.0.1 and nothing else -- no DNS, no internet, no
    external host. It is the only place the Shadowsocks handshake runs
    over a socket, and it is what turns the unit tests above from "the
    pieces are individually right" into "the pieces compose into something
    a server written from the spec understands".
    """

    def target(self, server, password="hunter2", cipher=None):
        return ProxyTarget(
            id=1,
            protocol=ProxyProtocol.SHADOWSOCKS.value,
            host=server.address[0],
            port=server.address[1],
            password=password,
            ss_method=cipher or server.cipher,
        )

    def run_probe(self, server, timeout=5.0, **kwargs):
        server.start()
        self.addCleanup(server.stop)
        try:
            return SocketProber().probe(
                self.target(server, **kwargs),
                destination=("probe.invalid", 443),
                timeout=timeout,
            )
        finally:
            server.stop()
            server.join(timeout=5)

    def test_a_working_proxy_probes_successfully(self):
        for cipher in ("aes-128-gcm", "aes-256-gcm", "chacha20-ietf-poly1305"):
            with self.subTest(cipher=cipher):
                server = _ReferenceServer("hunter2", cipher)
                result = self.run_probe(server)
                self.assertIsNone(server.error)
                self.assertTrue(result.succeeded, result.detail)
                self.assertIsNotNone(result.latency_ms)

    def test_the_server_receives_the_destination_we_asked_for(self):
        """The request header is a real SOCKS5 address block that an
        independent parser reads back correctly."""
        server = _ReferenceServer("hunter2", "aes-256-gcm")
        self.run_probe(server)
        self.assertEqual(server.received_address, ("probe.invalid", 443))

    def test_the_payload_is_a_real_tls_client_hello(self):
        """Something has to be sent or no reply ever comes back."""
        server = _ReferenceServer("hunter2", "aes-256-gcm")
        self.run_probe(server)
        payload = server.received_payload
        self.assertEqual(payload[0], 0x16, "TLS handshake record")
        self.assertEqual(payload[5], 0x01, "ClientHello")

    def test_silence_is_reported_as_unverifiable_not_as_auth_failed(self):
        """The honest answer. A server that accepts the connection and
        says nothing is indistinguishable from a wrong password, and
        claiming either cause would be a guess."""
        server = _ReferenceServer("hunter2", "aes-256-gcm", behaviour="silence")
        result = self.run_probe(server)
        self.assertFalse(result.succeeded)
        self.assertEqual(result.error_kind, ProbeErrorKind.UNVERIFIABLE)
        self.assertIn("identical on the wire", result.detail)

    def test_a_server_that_hangs_is_also_unverifiable_not_timeout(self):
        """A held-open connection and a closed one are the same verdict.

        `timeout` would imply the host is unreachable, and the TCP
        connection plainly succeeded. Collapsing both shapes of silence
        onto one kind is the point: two different-looking verdicts for
        one indistinguishable situation is worse than saying so.
        """
        server = _ReferenceServer("hunter2", "aes-256-gcm", behaviour="hold")
        result = self.run_probe(server, timeout=1.0)
        self.assertFalse(result.succeeded)
        self.assertEqual(result.error_kind, ProbeErrorKind.UNVERIFIABLE)

    def test_a_wrong_password_against_a_silent_server_is_also_unverifiable(self):
        """The same silence, the same verdict -- deliberately. The probe
        does not pretend to know which of the two it hit.

        This is the case the task calls out: here a wrong password really
        is indistinguishable from a dead upstream, and the result says
        exactly that rather than guessing `auth_failed`.
        """
        server = _ReferenceServer("hunter2", "aes-256-gcm", behaviour="silence")
        result = self.run_probe(server, password="wrong")
        self.assertEqual(result.error_kind, ProbeErrorKind.UNVERIFIABLE)

    def test_a_wrong_password_is_auth_failed_when_the_server_does_reply(self):
        """The case the protocol *does* permit a verdict on.

        Needs a server that answers without first decrypting the request,
        because a conforming one would not answer at all -- which is
        precisely why the silent case above cannot be resolved.
        """
        server = _ReferenceServer("hunter2", "aes-256-gcm", behaviour="reply_blind")
        result = self.run_probe(server, password="definitely-not-it")
        self.assertFalse(result.succeeded)
        self.assertEqual(result.error_kind, ProbeErrorKind.AUTH_FAILED)
        self.assertIn("wrong password", result.detail)

    def test_a_wrong_cipher_is_auth_failed_when_the_server_replies(self):
        server = _ReferenceServer("hunter2", "aes-256-gcm", behaviour="reply_blind")
        result = self.run_probe(server, cipher="chacha20-ietf-poly1305")
        self.assertEqual(result.error_kind, ProbeErrorKind.AUTH_FAILED)

    def test_a_server_sealing_under_another_key_is_auth_failed(self):
        server = _ReferenceServer("hunter2", "aes-256-gcm", behaviour="wrong_key")
        result = self.run_probe(server)
        self.assertEqual(result.error_kind, ProbeErrorKind.AUTH_FAILED)

    def test_random_bytes_from_a_non_shadowsocks_port_are_auth_failed(self):
        """Something is listening and it is not this protocol. Reported as
        a failure, because nothing usable is there -- but never as a
        success, which a bare TCP connect would have called it."""
        server = _ReferenceServer("hunter2", "aes-256-gcm", behaviour="garbage")
        result = self.run_probe(server)
        self.assertFalse(result.succeeded)
        self.assertEqual(result.error_kind, ProbeErrorKind.AUTH_FAILED)

    def test_an_unreachable_host_is_distinguishable_from_a_wrong_password(self):
        """The distinction the task hinges on: a dead *host* is reported
        precisely, because the TCP connection fails before any
        Shadowsocks logic runs."""
        closed = socket.socket()
        closed.bind(("127.0.0.1", 0))
        address = closed.getsockname()
        closed.close()

        result = SocketProber().probe(
            ProxyTarget(
                id=1,
                protocol=ProxyProtocol.SHADOWSOCKS.value,
                host=address[0],
                port=address[1],
                password="hunter2",
                ss_method="aes-256-gcm",
            ),
            destination=("probe.invalid", 443),
            timeout=3.0,
        )
        self.assertFalse(result.succeeded)
        self.assertIn(
            result.error_kind,
            (ProbeErrorKind.REFUSED, ProbeErrorKind.TIMEOUT, ProbeErrorKind.UNKNOWN),
        )
        self.assertNotEqual(result.error_kind, ProbeErrorKind.UNVERIFIABLE)
        self.assertNotEqual(result.error_kind, ProbeErrorKind.AUTH_FAILED)


# ---------------------------------------------------------------------------
# 9. Dispatch: SS is no longer skipped, SS2022 still is
# ---------------------------------------------------------------------------


class ShadowsocksDispatchTests(TestCase):
    """`handler_for` -- resolved before any socket is opened."""

    def ss_target(self, method):
        return ProxyTarget(
            id=1,
            protocol=ProxyProtocol.SHADOWSOCKS.value,
            host="198.51.100.22",
            port=8388,
            password="hunter2",
            ss_method=method,
        )

    def test_shadowsocks_now_resolves_to_a_handler(self):
        """P14: SS proxies are no longer skipped."""
        prober = SocketProber()
        for method in ("aes-128-gcm", "aes-256-gcm", "chacha20-ietf-poly1305"):
            with self.subTest(method=method):
                self.assertTrue(
                    callable(
                        prober.handler_for(
                            ProxyProtocol.SHADOWSOCKS.value, self.ss_target(method)
                        )
                    )
                )

    def test_ss2022_is_skipped_and_labelled_as_a_cipher_gap(self):
        """Our gap, not a dead proxy -- and distinguishable from an
        unknown protocol so a run can report which."""
        with self.assertRaises(ProbeUnsupported) as caught:
            SocketProber().handler_for(
                ProxyProtocol.SHADOWSOCKS.value,
                self.ss_target("2022-blake3-aes-256-gcm"),
            )
        self.assertEqual(caught.exception.code, ProbeUnsupported.UNSUPPORTED_CIPHER)
        self.assertIn("2022", str(caught.exception))

    def test_a_missing_cipher_is_skipped_rather_than_guessed(self):
        with self.assertRaises(ProbeUnsupported) as caught:
            SocketProber().handler_for(
                ProxyProtocol.SHADOWSOCKS.value, self.ss_target("")
            )
        self.assertEqual(caught.exception.code, ProbeUnsupported.UNSUPPORTED_CIPHER)

    def test_an_unknown_protocol_carries_the_other_code(self):
        with self.assertRaises(ProbeUnsupported) as caught:
            SocketProber().handler_for("carrier-pigeon")
        self.assertEqual(caught.exception.code, ProbeUnsupported.UNSUPPORTED_PROTOCOL)

    def test_the_cipher_check_costs_no_tcp_connection(self):
        """An inventory of SS2022 proxies must not open a socket each.

        Asserted by resolving the handler with no server anywhere near the
        recorded address and no socket module patching -- if `handler_for`
        connected, this would hang rather than raise.
        """
        with self.assertRaises(ProbeUnsupported):
            SocketProber().handler_for(
                ProxyProtocol.SHADOWSOCKS.value,
                self.ss_target("2022-blake3-chacha20-poly1305"),
            )

    def test_a_batch_records_the_skip_code_per_proxy(self):
        class CipherProber(SocketProber):
            pass

        targets = [self.ss_target("2022-blake3-aes-256-gcm")]
        outcome = probe_batch(CipherProber(), targets)
        self.assertEqual(outcome.results, [])
        self.assertEqual(
            outcome.skipped_codes, {1: ProbeUnsupported.UNSUPPORTED_CIPHER}
        )
        self.assertEqual(
            outcome.skip_reason_counts(),
            {ProbeUnsupported.UNSUPPORTED_CIPHER: 1},
        )
